"Password": "ପାସୱାର୍ଡ",
"Caps Lock is on": "Caps Lock ଚାଲୁ ଅଛି",
"Signing in…": "ସାଇନ୍ ଇନ୍ ହେଉଛି…",
"Sign in": "ସାଇନ୍ ଇନ୍",
"Forgot password?": "ପାସୱାର୍ଡ ଭୁଲିଗଲେ?",
"Don't have an account?": "ଆକାଉଣ୍ଟ୍ ନାହିଁ?",
"Sign up": "ସାଇନ୍ ଅପ୍",
"Password strength:": "ପାସୱାର୍ଡ ଶକ୍ତି:",
"(done)": "(ହୋଇଗଲା)",
"(not yet)": "(ବାକି ଅଛି)",
"Create your account": "ଆପଣଙ୍କ ଆକାଉଣ୍ଟ୍ ତିଆରି କରନ୍ତୁ",
"Join GetRemindMe and conquer your deadlines.": "GetRemindMe ରେ ଯୋଗ ଦିଅନ୍ତୁ ଓ ଆପଣଙ୍କ ଡେଡଲାଇନ୍ ଜିତନ୍ତୁ।",
"Free. Takes about 30 seconds.": "ମାଗଣା। ପ୍ରାୟ ୩୦ ସେକେଣ୍ଡ ଲାଗିବ।",
"Create account": "ଆକାଉଣ୍ଟ୍ ତିଆରି କରନ୍ତୁ",
"Username": "ୟୁଜରନେମ୍",
"Choose a username": "ଏକ ୟୁଜରନେମ୍ ବାଛନ୍ତୁ",
"Create a password": "ଏକ ପାସୱାର୍ଡ ତିଆରି କରନ୍ତୁ",
"Confirm password": "ପାସୱାର୍ଡ ନିଶ୍ଚିତ କରନ୍ତୁ",
"Confirm your password": "ଆପଣଙ୍କ ପାସୱାର୍ଡ ନିଶ୍ଚିତ କରନ୍ତୁ",
"Passwords match": "ପାସୱାର୍ଡ ମେଳ ଖାଉଛି",
"Creating account…": "ଆକାଉଣ୍ଟ୍ ତିଆରି ହେଉଛି…",
"Please fix the highlighted fields to continue.": "ଆଗକୁ ବଢ଼ିବାକୁ ହାଇଲାଇଟ୍ ହୋଇଥିବା ଫିଲ୍ଡଗୁଡ଼ିକୁ ସଠିକ୍ କରନ୍ତୁ।",
"By clicking Create account, you agree to our": "ଆକାଉଣ୍ଟ୍ ତିଆରି କରନ୍ତୁ କ୍ଲିକ୍ କରିବାରୁ, ଆପଣ ଆମର",
"Terms of Service": "ସେବା ସର୍ତ୍ତାବଳୀ",
