"GetRemindMe: Specific, Daily & Weekly Reminders": "GetRemindMe: ନିର୍ଦ୍ଦିଷ୍ଟ, ଦୈନିକ ଓ ସାପ୍ତାହିକ ରିମାଇଣ୍ଡର",
"GetRemindMe sends specific, daily and weekly reminders to Telegram and your browser. Type or speak a task, try it free without signing up, and never miss a deadline or habit again.": "GetRemindMe Telegram ଓ ଆପଣଙ୍କ ବ୍ରାଉଜର୍‌କୁ ନିର୍ଦ୍ଦିଷ୍ଟ, ଦୈନିକ ଓ ସାପ୍ତାହିକ ରିମାଇଣ୍ଡର ପଠାଏ। କାମ ଟାଇପ୍ ବା କୁହନ୍ତୁ, ସାଇନ୍ ଅପ୍ ନକରି ମାଗଣାରେ ଚେଷ୍ଟା କରନ୍ତୁ, ଏବଂ କେବେ ଡେଡଲାଇନ୍ ବା ଅଭ୍ୟାସ ଛାଡ଼ନ୍ତୁ ନାହିଁ।",
"About GetRemindMe: a reminder app for specific, daily and weekly reminders with Magic Add AI, Telegram and browser notifications, and encrypted private reminders.": "GetRemindMe ବିଷୟରେ: Magic Add AI, Telegram ଓ ବ୍ରାଉଜର୍ ନୋଟିଫିକେସନ୍, ଏବଂ ଏନକ୍ରିପ୍ଟ ହୋଇଥିବା ବ୍ୟକ୍ତିଗତ ରିମାଇଣ୍ଡର ସହ ନିର୍ଦ୍ଦିଷ୍ଟ, ଦୈନିକ ଓ ସାପ୍ତାହିକ ରିମାଇଣ୍ଡର ପାଇଁ ଏକ ରିମାଇଣ୍ଡର ଆପ୍।",
"FAQs & Help": "FAQs ଓ ସାହାଯ୍ୟ",
"Answers about GetRemindMe: daily, weekly and one-time reminders, Magic Add, Telegram and browser notifications, privacy and your account.": "GetRemindMe ବିଷୟରେ ଉତ୍ତର: ଦୈନିକ, ସାପ୍ତାହିକ ଓ ଏକ ଥରର ରିମାଇଣ୍ଡର, Magic Add, Telegram ଓ ବ୍ରାଉଜର୍ ନୋଟିଫିକେସନ୍, ଗୋପନୀୟତା ଓ ଆପଣଙ୍କ ଆକାଉଣ୍ଟ୍।",
"Terms of Service & Privacy Policy": "ସେବା ସର୍ତ୍ତାବଳୀ ଓ ଗୋପନୀୟତା ନୀତି",
"Read the GetRemindMe Terms of Service and Privacy Policy: how your reminders are encrypted, which notification channels we use, and how to delete your data.": "GetRemindMe ସେବା ସର୍ତ୍ତାବଳୀ ଓ ଗୋପନୀୟତା ନୀତି ପଢ଼ନ୍ତୁ: ଆପଣଙ୍କ ରିମାଇଣ୍ଡର କିପରି ଏନକ୍ରିପ୍ଟ ହୁଏ, ଆମେ କେଉଁ ନୋଟିଫିକେସନ୍ ମାଧ୍ୟମ ବ୍ୟବହାର କରୁ, ଏବଂ ଆପଣଙ୍କ ତଥ୍ୟ କିପରି ଡିଲିଟ୍ କରିବେ।",
"Log in to GetRemindMe to see your reminders and manage daily, weekly and one-time alerts.": "ଆପଣଙ୍କ ରିମାଇଣ୍ଡର ଦେଖିବା ଓ ଦୈନିକ, ସାପ୍ତାହିକ ଓ ଏକ ଥରର ଆଲର୍ଟ ପରିଚାଳନା କରିବାକୁ GetRemindMe ରେ ଲଗ୍ ଇନ୍ କରନ୍ତୁ।",
"Create your free account": "ଆପଣଙ୍କ ମାଗଣା ଆକାଉଣ୍ଟ୍ ତିଆରି କରନ୍ତୁ",
"Sign up for GetRemindMe free and get specific, daily and weekly reminders on Telegram and in your browser.": "GetRemindMe ରେ ମାଗଣାରେ ସାଇନ୍ ଅପ୍ କରନ୍ତୁ ଓ Telegram ଏବଂ ଆପଣଙ୍କ ବ୍ରାଉଜର୍‌ରେ ନିର୍ଦ୍ଦିଷ୍ଟ, ଦୈନିକ ଓ ସାପ୍ତାହିକ ରିମାଇଣ୍ଡର ପାଆନ୍ତୁ।",
