"You appear to be offline. Check your connection and try again.": "ଆପଣ ଅଫଲାଇନ୍ ଥିବା ପରି ଲାଗୁଛି। ଆପଣଙ୍କ ସଂଯୋଗ ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
"We couldn't connect right now. Please check your internet connection and try again.": "ଆମେ ଏବେ ସଂଯୋଗ କରିପାରିଲୁ ନାହିଁ। ଦୟାକରି ଆପଣଙ୍କ ଇଣ୍ଟରନେଟ୍ ସଂଯୋଗ ଦେଖି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
"Your session has expired. Please log in again.": "ଆପଣଙ୍କ ସେସନ୍ ଶେଷ ହୋଇଛି। ଦୟାକରି ପୁଣି ଲଗ୍ ଇନ୍ କରନ୍ତୁ।",
"You don't have permission to do that.": "ଏହା କରିବାକୁ ଆପଣଙ୍କର ଅନୁମତି ନାହିଁ।",
"We couldn't find that. It may have been removed.": "ଆମେ ତାହା ପାଇଲୁ ନାହିଁ। ଏହା ହଟାଯାଇଥାଇପାରେ।",
"That file is too large.": "ଫାଇଲ୍ ବହୁତ ବଡ଼।",
"Too many attempts. Please wait a moment and try again.": "ବହୁତ ଥର ଚେଷ୍ଟା ହେଲା। ଦୟାକରି କିଛି ସମୟ ଅପେକ୍ଷା କରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
"The service is busy right now. Please try again shortly.": "ସେବା ଏବେ ବ୍ୟସ୍ତ ଅଛି। ଦୟାକରି କିଛି ସମୟ ପରେ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
"Other": "ଅନ୍ୟାନ୍ୟ",
"Service worker is not active. Test push on a production build (npm run build && npm run preview) or the deployed site.": "ସର୍ଭିସ୍ ୱାର୍କର୍ ସକ୍ରିୟ ନାହିଁ। ପ୍ରୋଡକ୍ସନ୍ ବିଲ୍ଡ (npm run build && npm run preview) ବା ଡେପ୍ଲୟ ହୋଇଥିବା ସାଇଟ୍‌ରେ ପୁଶ୍ ଟେଷ୍ଟ କରନ୍ତୁ।",
"Error checking local push subscription:": "ଲୋକାଲ୍ ପୁଶ୍ ସବ୍‌ସ୍କ୍ରିପସନ୍ ଯାଞ୍ଚ କରିବାରେ ତ୍ରୁଟି:",
"Push is not supported here. On iPhone, add the site to your Home Screen first.": "ଏଠାରେ ପୁଶ୍ ସମର୍ଥିତ ନୁହେଁ। iPhone ରେ, ପ୍ରଥମେ ସାଇଟ୍‌କୁ ହୋମ୍ ସ୍କ୍ରିନ୍‌ରେ ଯୋଡ଼ନ୍ତୁ।",
"Push alerts are not configured on this site yet.": "ଏହି ସାଇଟ୍‌ରେ ପୁଶ୍ ଆଲର୍ଟ ଏପର୍ଯ୍ୟନ୍ତ କନଫିଗର୍ ହୋଇନାହିଁ।",
"Notifications are blocked. Allow them in your browser or site settings and try again.": "ନୋଟିଫିକେସନ୍ ବ୍ଲକ୍ ଅଛି। ଆପଣଙ୍କ ବ୍ରାଉଜର୍ ବା ସାଇଟ୍ ସେଟିଂସ୍‌ରେ ଅନୁମତି ଦେଇ ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
