"Could not enable alerts. Please try again.": "ଆଲର୍ଟ ଚାଲୁ କରିପାରିଲୁ ନାହିଁ। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।",
