"Everyday life": "ଦୈନନ୍ଦିନ ଜୀବନ",
"Bills, habits and the small things that are easy to forget.": "ବିଲ୍, ଅଭ୍ୟାସ ଓ ଭୁଲିବା ସହଜ ଛୋଟ କଥା।",
"A reminder service for students and busy people": "ଛାତ୍ରଛାତ୍ରୀ ଓ ବ୍ୟସ୍ତ ଲୋକଙ୍କ ପାଇଁ ରିମାଇଣ୍ଡର୍ ସେବା",
"Forget less.": "କମ୍ ଭୁଲନ୍ତୁ।",
"Do more.": "ଅଧିକ କରନ୍ତୁ।",
