"See the services": "ସେବା ଦେଖନ୍ତୁ",
"· Free APK, no Play Store needed": "· ମାଗଣା APK, Play Store ଦରକାର ନାହିଁ",
"Free to use": "ମାଗଣା",
"Works offline": "ଅଫଲାଇନ୍ରେ ମଧ୍ୟ ଚାଲେ",
"Encrypted at rest": "ଏନକ୍ରିପ୍ଟ କରି ରଖାଯାଏ",
"Why you can trust it": "ଆପଣ କାହିଁକି ଭରସା କରିପାରିବେ",
"A reminder that rings when it says it will": "ଯେତେବେଳେ କହେ ସେତେବେଳେ ହିଁ ବାଜୁଥିବା ରିମାଇଣ୍ଡର୍",
"Heads-ups before, an alarm on the dot, and a way to tick it off. This is what happens for one reminder.": "ଆଗୁଆ ସୂଚନା, ଠିକ୍ ସମୟରେ ଆଲାର୍ମ, ଓ ଟିକ୍ କରିବାର ଉପାୟ। ଗୋଟିଏ ରିମାଇଣ୍ଡର୍ ସହ ଏହାହିଁ ହୁଏ।",
"What GetRemindMe does for you": "GetRemindMe ଆପଣଙ୍କ ପାଇଁ କ'ଣ କରେ",
"Six things, done properly, so a deadline never depends on your memory.": "ଛଅଟି ଜିନିଷ, ଠିକ୍ ଭାବେ, ଯେପରି ସମୟସୀମା ଆପଣଙ୍କ ସ୍ମୃତି ଉପରେ ନିର୍ଭର ନକରେ।",
"From a sentence to a nudge, in three steps": "ଗୋଟିଏ ବାକ୍ୟରୁ ମନେ ପକାଇବା ପର୍ଯ୍ୟନ୍ତ, ତିନି ପଦକ୍ଷେପରେ",
"Built around real deadlines": "ପ୍ରକୃତ ସମୟସୀମା ଚାରିପାଖେ ତିଆରି",
"Whatever you are keeping track of, you say it the way you would tell a friend.": "ଯାହା ଟ୍ରାକ୍ କରୁଛନ୍ତି, ବନ୍ଧୁଙ୍କୁ କହିଲା ଭଳି କୁହନ୍ତୁ।",
"Delivery": "ପହଞ୍ଚାଇବା",
"It finds you, wherever you are": "ଆପଣ ଯେଉଁଠି ଥାଆନ୍ତୁ, ଏହା ଆପଣଙ୍କୁ ଖୋଜିନିଏ",
"A push in the browser, a message in Telegram, or an alarm from the Android app. Pick what suits you.": "ବ୍ରାଉଜର୍ରେ ପୁଶ୍, Telegramରେ ବାର୍ତ୍ତା, ବା Android ଆପ୍ରୁ ଆଲାର୍ମ। ଯାହା ଭଲ ଲାଗେ ବାଛନ୍ତୁ।",
"Browser push": "ବ୍ରାଉଜର୍ ପୁଶ୍",
