"Due in 10 minutes. ‘DBMS assignment’ is due in 10 minutes. Time to wrap it up.": "୧୦ ମିନିଟରେ ସମୟସୀମା। ‘DBMS assignment’ ସମୟସୀମା ୧୦ ମିନିଟରେ। ଏବେ ସାରିଦିଅନ୍ତୁ।",
